import{_ as t,o as a,c as d,ai as s}from"./chunks/framework.C33Uq6m-.js";const p=JSON.parse('{"title":"Modèles","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/models.md","filePath":"fr/guide/models.md"}'),o={name:"fr/guide/models.md"};function l(r,e,i,n,m,c){return a(),d("div",null,[...e[0]||(e[0]=[s('<h1 id="modeles" tabindex="-1">Modèles <a class="header-anchor" href="#modeles" aria-label="Permalink to &quot;Modèles&quot;">​</a></h1><p>La page Modèles est un navigateur pour tous les modèles installés dans votre instance Ollama locale, avec des métadonnées détaillées et la détection des capacités.</p><p><strong>Élément de la barre latérale :</strong> Modèles <strong>Route :</strong> <code>/settings?tab=models</code></p><h2 id="vue-d-ensemble-de-l-interface" tabindex="-1">Vue d&#39;ensemble de l&#39;interface <a class="header-anchor" href="#vue-d-ensemble-de-l-interface" aria-label="Permalink to &quot;Vue d&#39;ensemble de l&#39;interface&quot;">​</a></h2><p>La page Modèles (accessible via l&#39;onglet Paramètres &gt; Modèles) affiche une carte ou une liste pour chaque modèle installé avec les informations essentielles en un coup d&#39;œil.</p><h2 id="details-des-modeles" tabindex="-1">Détails des modèles <a class="header-anchor" href="#details-des-modeles" aria-label="Permalink to &quot;Détails des modèles&quot;">​</a></h2><p>Chaque carte de modèle affiche :</p><table tabindex="0"><thead><tr><th>Champ</th><th>Description</th></tr></thead><tbody><tr><td><strong>Nom</strong></td><td>Identifiant du modèle (par ex., <code>llama3.2:latest</code>)</td></tr><tr><td><strong>Nombre de paramètres</strong></td><td>Nombre de paramètres (par ex., 3B, 7B, 70B)</td></tr><tr><td><strong>Quantification</strong></td><td>Niveau de compression (par ex., Q4_0, Q8_0, F16)</td></tr><tr><td><strong>Famille</strong></td><td>Famille du modèle (par ex., llama, mistral, gemma)</td></tr><tr><td><strong>Format</strong></td><td>Format du modèle (par ex., gguf)</td></tr></tbody></table><h2 id="diagrammes-d-architecture" tabindex="-1">Diagrammes d&#39;architecture <a class="header-anchor" href="#diagrammes-d-architecture" aria-label="Permalink to &quot;Diagrammes d&#39;architecture&quot;">​</a></h2><p>Cliquez sur un modèle pour voir un diagramme d&#39;architecture montrant la structure interne du modèle -- nombre de couches, têtes d&#39;attention, dimensions d&#39;embedding, et plus encore. Ces informations sont extraites des métadonnées du modèle fournies par Ollama.</p><h2 id="detection-des-capacites" tabindex="-1">Détection des capacités <a class="header-anchor" href="#detection-des-capacites" aria-label="Permalink to &quot;Détection des capacités&quot;">​</a></h2><p>LLMxRay détecte automatiquement ce que chaque modèle peut faire :</p><table tabindex="0"><thead><tr><th>Capacité</th><th>Comment elle est détectée</th><th>Effet sur l&#39;interface</th></tr></thead><tbody><tr><td><strong>Raisonnement</strong></td><td>Patterns dans le nom du modèle (par ex., <code>deepseek-r1</code>) ou capacités Ollama</td><td>Active l&#39;onglet raisonnement dans Diagnostics de Chat</td></tr><tr><td><strong>Vision</strong></td><td>Capacités Ollama ou famille du modèle</td><td>Active les pièces jointes images dans le chat</td></tr><tr><td><strong>Embedding</strong></td><td>Capacités Ollama ou famille du modèle</td><td>Apparaît dans les sélecteurs de modèles des pages Plongements et Base de Connaissances</td></tr><tr><td><strong>Appel d&#39;outils</strong></td><td>Capacités Ollama</td><td>Active l&#39;appel d&#39;outils dans le chat</td></tr></tbody></table><p>Les modèles ne prenant en charge que les embeddings sont automatiquement filtrés des sélecteurs de modèles de chat.</p><h2 id="catalogue-de-modeles" tabindex="-1">Catalogue de modèles <a class="header-anchor" href="#catalogue-de-modeles" aria-label="Permalink to &quot;Catalogue de modèles&quot;">​</a></h2><p>Le catalogue offre une vue organisée des modèles disponibles avec des tableaux comparatifs, vous aidant à choisir le modèle adapté à votre cas d&#39;utilisation.</p><h2 id="astuces" tabindex="-1">Astuces <a class="header-anchor" href="#astuces" aria-label="Permalink to &quot;Astuces&quot;">​</a></h2><ul><li><strong>Compromis de quantification</strong> -- Une quantification basse (Q4) utilise moins de RAM mais réduit légèrement la qualité. Q8 et F16 offrent une meilleure qualité mais nécessitent plus de mémoire.</li><li><strong>Télécharger d&#39;autres modèles</strong> depuis le terminal : <code>ollama pull &lt;nom-du-modele&gt;</code></li><li>La détection des capacités adapte l&#39;ensemble de l&#39;interface -- vous n&#39;avez rien à configurer manuellement.</li></ul>',18)])])}const h=t(o,[["render",l]]);export{p as __pageData,h as default};
